/*
 * Tree files support: store the exported device as a tree of small
 * block files (TREEPAGESIZE bytes each, at most TREEDIRSIZE files or
 * subdirectories per directory), with the nesting level chosen based
 * on the total size of the export. See nbd-server(5).
 */

#include <fcntl.h>
#include <limits.h> // for PATH_MAX
#include <inttypes.h>
#include <stdio.h>
#include <unistd.h>
